code='''def transform(grid):
    g=[r[:] for r in grid]
    # Connect identical colored blocks across aligned tile rows and columns.
    H=len(g); W=len(g[0])
    comps=[]; seen=set()
    for y in range(H):
      for x in range(W):
        c=g[y][x]
        if c in (0,4) or (y,x) in seen: continue
        q=[(y,x)]; seen.add((y,x)); cells=[]
        while q:
          a,b=q.pop(); cells.append((a,b))
          for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            u,v=a+da,b+db
            if 0<=u<H and 0<=v<W and (u,v) not in seen and g[u][v]==c:
              seen.add((u,v)); q.append((u,v))
        ys=[a for a,b in cells]; xs=[b for a,b in cells]
        comps.append((c,min(ys),max(ys),min(xs),max(xs)))
    for i,a in enumerate(comps):
      c,t,b,l,r=a
      for d in comps[i+1:]:
        cc,T,B,L,R=d
        if c!=cc: continue
        if t==T and b==B:
          if r<L:
            for y in range(t,b+1):
              for x in range(r+1,L): g[y][x]=c
